mapper.select:
SELECT dept_code AS deptCode, dept_name AS deptName, SUM(NVL(total_visits, 0)) AS totalVisits, SUM(NVL(visit_count, 0)) AS visitCount, ROUND(AVG(NVL(efficiency, 0)), 2) AS avgEfficiency, SUM(NVL(effective_units, 0)) AS effectiveUnits, SUM(NVL(total_units, 0)) AS totalUnits, COUNT(DISTINCT stat_date) AS daysCount, COUNT(1) AS recordCount FROM TR_OUTP_OP WHERE stat_date BETWEEN #{startDate} AND #{endDate}
AND dept_code = #{deptCode}
GROUP BY dept_code, dept_name ORDER BY totalVisits DESC
